"""Fill HWPX template with JSON data."""

import json
import os
import re
import xml.etree.ElementTree as ET
import zipfile

BASE_DIR = '/tmp/hwpx_work/template_contents'
OUTPUT_PATH = '/root/training_feedback_ready.hwpx'

# Register namespace BEFORE any parsing to prevent tag renaming
HWP_NS = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
ET.register_namespace('hp', HWP_NS)

# Load JSON data
with open('/root/training_feedback.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# Build replacement map
replacements = {}

for key, value in data.items():
    if key == '참석자수':
        # Extract digits only: "32명" -> "32"
        digits = re.search(r'\d+', value)
        replacements[f'{{{key}}}'] = digits.group() if digits else value
    elif key == '만족도':
        # Extract numeric score: "4.5/5.0" -> "4.5점 (5.0점 만점)"
        match = re.search(r'([\d.]+)', value)
        if match:
            score = match.group(1)
            replacements[f'{{{key}}}'] = f'{score}점 (5.0점 만점)'
        else:
            replacements[f'{{{key}}}'] = value
    elif key == '종합의견':
        # Append " 후속 심화반 검토 요망." with proper spacing
        if value.endswith(' '):
            replacements[f'{{{key}}}'] = value + '후속 심화반 검토 요망.'
        else:
            replacements[f'{{{key}}}'] = value + ' 후속 심화반 검토 요망.'
    else:
        replacements[f'{{{key}}}'] = value

print("Replacement map:")
for k, v in replacements.items():
    print(f"  {k} -> {v}")

# Process each section XML
section_files = sorted([f for f in os.listdir(os.path.join(BASE_DIR, 'Contents')) if f.startswith('section') and f.endswith('.xml')])

for section_file in section_files:
    filepath = os.path.join(BASE_DIR, 'Contents', section_file)
    print(f"\nProcessing {section_file}...")

    # Parse XML
    tree = ET.parse(filepath)
    root = tree.getroot()

    modified_paragraphs = set()

    # Walk all elements and replace placeholders in text/tail
    for elem in root.iter():
        # Check and replace in .text
        if elem.text and '{{' in elem.text:
            for placeholder, replacement in replacements.items():
                if placeholder in elem.text:
                    elem.text = elem.text.replace(placeholder, replacement)
                    # Find parent paragraph
                    parent = root.find(f".//*[@id='{elem.get('id')}']..") if elem.get('id') else None
                    # Actually, traverse up to find hp:p
                    for p in root.iter(f'{{{HWP_NS}}}p'):
                        for child in p.iter():
                            if child is elem:
                                modified_paragraphs.add(p)
                                break

        # Check and replace in .tail
        if elem.tail and '{{' in elem.tail:
            for placeholder, replacement in replacements.items():
                if placeholder in elem.tail:
                    elem.tail = elem.tail.replace(placeholder, replacement)

    # Re-walk to find all paragraphs containing replaced text
    # (simpler approach: check all paragraphs for remaining '{{')
    for p in root.iter(f'{{{HWP_NS}}}p'):
        # Convert paragraph to string to check for placeholders
        text_content = ''.join([t.text or '' for t in p.iter()])
        if any(ph in text_content for ph in replacements.keys()):
            modified_paragraphs.add(p)

    # Remove lineSegArray from modified paragraphs
    for p in modified_paragraphs:
        for linesegarray in p.findall(f'{{{HWP_NS}}}linesegarray'):
            p.remove(linesegarray)

    # Write back XML with proper declaration
    tree.write(filepath, xml_declaration=True, encoding='UTF-8')
    print(f"  Modified {len(modified_paragraphs)} paragraphs, removed lineSegArray elements")

# Verify no placeholders remain
print("\nVerifying no placeholders remain...")
placeholder_count = 0
for section_file in section_files:
    filepath = os.path.join(BASE_DIR, 'Contents', section_file)
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
        if '{{' in content:
            placeholder_count += content.count('{{')
            print(f"  WARNING: Found {{...}} in {section_file}")

if placeholder_count == 0:
    print("  OK: No placeholders remain")
else:
    print(f"  ERROR: {placeholder_count} placeholders remain")

# Repackage HWPX
print(f"\nRepackaging to {OUTPUT_PATH}...")
with zipfile.ZipFile(OUTPUT_PATH, 'w') as zf:
    # mimetype MUST be first and uncompressed
    mimetype_path = os.path.join(BASE_DIR, 'mimetype')
    if os.path.exists(mimetype_path):
        zf.write(mimetype_path, 'mimetype', compress_type=zipfile.ZIP_STORED)
    else:
        print("  WARNING: mimetype not found")

    # Then add everything else
    for root_dir, dirs, files in os.walk(BASE_DIR):
        for fname in sorted(files):
            full_path = os.path.join(root_dir, fname)
            arcname = os.path.relpath(full_path, BASE_DIR)
            if arcname == 'mimetype':
                continue
            zf.write(full_path, arcname, compress_type=zipfile.ZIP_DEFLATED)

print(f"Done! Output written to {OUTPUT_PATH}")

