OUTPUT_PATH = '/root/training_feedback_ready.hwpx'

# Register namespace BEFORE any parsing to prevent tag renaming
HWP_NS = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
ET.register_namespace('hp', HWP_NS)

# Load JSON data
with open('/root/training_feedback.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# Build replacement map
replacements = {}

for key, value in data.items():
    if key == '참석자수':
        # Extract digits only: "32명" -> "32"
        digits = re.search(r'\d+', value)
        replacements[f'{{{key}}}'] = digits.group() if digits else value
    elif key == '만족도':
        # Extract numeric score: "4.5/5.0" -> "4.5점 (5.0점 만점)"
        match = re.search(r'([\d.]+)', value)
        if match:
            score = match.group(1)
            replacements[f'{{{key}}}'] = f'{score}점 (5.0점 만점)'
        else:
            replacements[f'{{{key}}}'] = value
    elif key == '종합의견':
        # Append " 후속 심화반 검토 요망." with proper spacing
        if value.endswith(' '):
            replacements[f'{{{key}}}'] = value + '후속 심화반 검토 요망.'
        else:
            replacements[f'{{{key}}}'] = value + ' 후속 심화반 검토 요망.'
    else:
        replacements[f'{{{key}}}'] = value

print("Replacement map:")
