            for placeholder, replacement in replacements.items():
                if placeholder in new_tail:
                    new_tail = new_tail.replace(placeholder, replacement)
                    has_placeholder = True
            if has_placeholder:
                elem.tail = new_tail

        # If this element had a placeholder, find its parent paragraph
        if has_placeholder:
            # Find parent paragraph by traversing up
            def find_parent(element, parent_map):
                for parent in root.iter():
                    for child in parent:
                        if child is element:
                            return parent
                return None

            # Build parent map
            parent_map = {c: p for p in root.iter() for c in p}
            current = elem
            while current is not None:
                if current.tag == hp_p:
                    modified_paragraphs.add(id(current))
                    break
                current = parent_map.get(current)

    # Alternative: check all paragraphs for any remaining '{{' to identify modified ones
    # and remove lineSegArray from them
    for p in root.iter(hp_p):
        # Check if paragraph contains any replaced text
        p_str = ET.tostring(p, encoding='unicode')
        if any(repl in p_str for repl in replacements.values()):
            # Remove lineSegArray from this paragraph
            for linesegarray in list(p.findall(hp_linesegarray)):
                p.remove(linesegarray)

    # Write back XML with proper declaration
    tree.write(filepath, xml_declaration=True, encoding='UTF-8')
    print(f"  Processed and removed lineSegArray elements")

